import{_ as o,o as e,c as i,a5 as l}from"./chunks/framework.DJo0M80U.js";const p=JSON.parse('{"title":"深度面试：浏览器中与任务执行、渲染和事件循环","description":"大纲 1. 概述 浏览器的工作原理简介 事件循环、任务和渲染的关系 文档中提到的核心概念 2. 浏览器事件循环 什么是事件循环 宏任务与微任务 事件循环的执行阶段 3. 宏任务与 setTimeout 宏任务的定义与类型 setTimeout 的工作机制 4ms 最小间隔与浏览器。","frontmatter":{"title":"深度面试：浏览器中与任务执行、渲染和事件循环","date":"2026-08-11T00:00:00.000Z","categories":["Vue 系统教程"],"tags":["Vue","Vue3","前端","教程","OneNote","工程化、质量与性能"],"description":"大纲 1. 概述 浏览器的工作原理简介 事件循环、任务和渲染的关系 文档中提到的核心概念 2. 浏览器事件循环 什么是事件循环 宏任务与微任务 事件循环的执行阶段 3. 宏任务与 setTimeout 宏任务的定义与类型 setTimeout 的工作机制 4ms 最小间隔与浏览器。","sidebarWeight":58,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/f-vue/性能优化/深度面试：浏览器中与任务执行、渲染和事件循环/深度面试：浏览器中与任务执行、渲染和事件循环.md"},"headers":[],"relativePath":"posts/Vue系统教程/06-工程化、质量与性能/深度面试：浏览器中与任务执行、渲染和事件循环/深度面试：浏览器中与任务执行、渲染和事件循环.md","filePath":"posts/Vue系统教程/06-工程化、质量与性能/深度面试：浏览器中与任务执行、渲染和事件循环/深度面试：浏览器中与任务执行、渲染和事件循环.md"}'),s={name:"posts/Vue系统教程/06-工程化、质量与性能/深度面试：浏览器中与任务执行、渲染和事件循环/深度面试：浏览器中与任务执行、渲染和事件循环.md"};function n(r,t,g,u,a,m){return e(),i("div",null,[...t[0]||(t[0]=[l('<div><h1 id="深度面试-浏览器中与任务执行、渲染和事件循环" tabindex="-1">深度面试：浏览器中与任务执行、渲染和事件循环 <a class="header-anchor" href="#深度面试-浏览器中与任务执行、渲染和事件循环" aria-label="Permalink to &quot;深度面试：浏览器中与任务执行、渲染和事件循环&quot;">​</a></h1><blockquote><p>本节目标：理解“深度面试：浏览器中与任务执行、渲染和事件循环”的核心思路，并能把它用于实际开发或面试表达。 <strong>大纲</strong></p></blockquote><ol><li><strong>概述</strong><ul><li>浏览器的工作原理简介</li><li>事件循环、任务和渲染的关系</li><li>文档中提到的核心概念</li></ul></li><li><strong>浏览器事件循环</strong><ul><li>什么是事件循环</li><li>宏任务与微任务</li><li>事件循环的执行阶段</li></ul></li><li><strong>宏任务与 setTimeout</strong><ul><li>宏任务的定义与类型</li><li>setTimeout 的工作机制</li><li>4ms 最小间隔与浏览器限制</li><li>漂移（Drift）问题</li><li>后台节流行为</li></ul></li><li><strong>浏览器渲染机制</strong><ul><li>渲染流水线简介</li><li>重绘（Repaint）与回流（Reflow）</li><li>渲染与事件循环的同步关系</li><li>帧率与 16.7ms 的重要性</li></ul></li><li><strong>与渲染同步的问题</strong><ul><li>更新抖动（Jank）的成因</li><li>如何与浏览器重绘对齐</li><li>requestAnimationFrame 的作用</li></ul></li><li><strong>累积延迟与实时性</strong><ul><li>累积延迟的来源</li><li>如何减少延迟</li><li>后台节流对实时性的影响</li></ul></li><li><strong>解决方案与最佳实践</strong><ul><li>使用 useRafFn 实现与渲染同步</li><li>节流与防抖的结合</li><li>处理后台节流问题</li></ul></li><li><strong>代码示例</strong><ul><li>简单的 setTimeout 示例</li><li>使用 requestAnimationFrame 同步渲染</li><li>节流的 useRafFn 实现</li><li>处理后台节流的检测</li></ul></li><li><strong>总结与注意事项</strong><ul><li>关键概念回顾</li><li>常见误区与建议</li></ul></li></ol><p><strong>详细说明</strong><strong>1. 概述</strong><strong>浏览器的工作原理简介</strong> 浏览器是一个复杂的软件系统，负责解析 HTML、CSS 和 JavaScript，渲染页面，并处理用户交互。其核心模块包括：</p><ul><li><strong>JavaScript 引擎</strong>：如 V8（Chrome）或 SpiderMonkey（Firefox），执行 JavaScript 代码。</li><li><strong>渲染引擎</strong>：如 Blink（Chrome）或 Gecko（Firefox），负责绘制页面。</li><li><strong>事件循环</strong>：协调 JavaScript 执行、用户交互和渲染更新。</li></ul><p>浏览器是单线程的，所有任务（代码执行、DOM 操作、渲染等）通过事件循环机制按顺序处理，确保页面响应性和流畅性。</p><p><strong>事件循环、任务和渲染的关系</strong></p><ul><li><strong>事件循环</strong>：浏览器通过事件循环（Event Loop）管理任务的执行顺序，将任务分为宏任务（Task）和微任务（Microtask），并在适当的时机触发渲染。</li><li><strong>任务</strong>：包括用户输入、定时器回调、网络请求等，分为宏任务和微任务。</li><li><strong>渲染</strong>：浏览器每 16.7 毫秒（60 FPS）尝试绘制一帧，渲染与事件循环的“绘制阶段”关联。</li></ul><p>文档中提到的 setTimeout、漂移、后台节流和更新抖动等问题，都与事件循环和渲染机制的交互密切相关。</p><p><strong>文档中提到的核心概念</strong></p><ul><li><strong>宏任务</strong>：setTimeout 注册的回调是宏任务，放在定时器阶段执行。</li><li><strong>4ms 最小间隔</strong>：浏览器将 setTimeout 的延迟限制为至少 4ms。</li><li><strong>漂移（Drift）</strong>：回调执行时间长会导致后续定时器延迟。</li><li><strong>后台节流</strong>：不可视页面中，定时器频率大幅降低。</li><li><strong>更新抖动</strong>：定时器回调与渲染不同步，导致视觉不连贯。</li><li><strong>与渲染同步</strong>：使用 requestAnimationFrame 可确保回调与浏览器重绘对齐。</li></ul><p><strong>2. 浏览器事件循环</strong><strong>什么是事件循环</strong> 事件循环是浏览器协调 JavaScript 执行、用户交互和渲染的机制。它不断检查任务队列，执行任务，并在适当的时机触发渲染。事件循环的核心目标是：</p><ul><li>确保 JavaScript 代码按顺序执行。</li><li>响应用户输入（如点击、键盘）。</li><li>保持页面渲染的流畅性（理想为 60 FPS，即每 16.7ms 一帧）。</li></ul><p>事件循环的伪代码如下： while (true) { <em>// 处理宏任务队列</em> while (macroTaskQueue.length &gt; 0) { const task = macroTaskQueue.shift(); execute(task); <em>// 执行所有微任务</em> while (microTaskQueue.length &gt; 0) { const microTask = microTaskQueue.shift(); execute(microTask); } } <em>// 渲染（如果需要）</em> if (needsRendering) { updateRendering(); } <em>// 等待新任务</em>}</p><p><strong>宏任务与微任务</strong></p><ul><li><strong>宏任务（Task）</strong>： <ul><li>包括：脚本执行、事件回调（点击、滚动）、setTimeout/setInterval 回调、I/O 操作（网络请求）、UI 渲染。</li><li>每次事件循环处理一个宏任务。</li><li>示例：setTimeout(() =&gt; console.log(&#39;宏任务&#39;), 1000)。</li></ul></li><li><strong>微任务（Microtask）</strong>： <ul><li>包括：Promise 回调、MutationObserver 回调、queueMicrotask。</li><li>在每个宏任务执行后，立即清空微任务队列。</li><li>示例：Promise.resolve().then(() =&gt; console.log(&#39;微任务&#39;))。</li></ul></li></ul><p><strong>事件循环的执行阶段</strong> 事件循环按以下阶段运行：</p><ol><li><strong>定时器阶段</strong>：检查是否有到期的 setTimeout/setInterval 回调，加入宏任务队列。</li><li><strong>I/O 回调阶段</strong>：处理网络请求、文件操作等回调。</li><li><strong>空闲阶段</strong>：处理 requestIdleCallback 回调（低优先级任务）。</li><li><strong>渲染阶段</strong>： <ul><li>更新 DOM（回流与重绘）。</li><li>执行 requestAnimationFrame 回调。</li><li>HTML 规范保证渲染在定时器阶段之后。</li></ul></li><li><strong>微任务阶段</strong>：在每个宏任务后，清空微任务队列。</li></ol><p>示例： console.log(&#39;开始&#39;);setTimeout(() =&gt; console.log(&#39;setTimeout&#39;), 0);Promise.resolve().then(() =&gt; console.log(&#39;Promise&#39;));console.log(&#39;结束&#39;); <em>// 输出：<strong>// 开始</strong>// 结束</em>_// Promise__// setTimeout_ <strong>解释</strong>：</p><ul><li>console.log(&#39;开始&#39;) 和 结束 是同步代码，立即执行。</li><li>Promise.then 是微任务，在当前宏任务结束后执行。</li><li>setTimeout 是宏任务，放入定时器队列，下一轮事件循环执行。</li></ul><p><strong>3. 宏任务与 setTimeout</strong><strong>宏任务的定义与类型</strong> 宏任务是事件循环中较大的执行单元，每个宏任务完成后会触发微任务队列的清空和可能的渲染。常见的宏任务包括：</p><ul><li>脚本执行（整个 &lt;script&gt; 块）。</li><li>事件回调（如 onclick）。</li><li>定时器回调（setTimeout、setInterval）。</li><li>网络请求回调（fetch 完成）。</li><li>UI 渲染任务。</li></ul><p><strong>setTimeout 的工作机制</strong> setTimeout(fn, delay) 注册一个宏任务，延迟 delay 毫秒后将回调 fn 放入宏任务队列。流程如下：</p><ol><li>浏览器记录定时器的触发时间（当前时间 + delay）。</li><li>到期后，将回调加入宏任务队列。</li><li>事件循环在定时器阶段处理该回调。</li></ol><p><strong>4ms 最小间隔与浏览器限制</strong></p><ul><li><strong>4ms Clamp</strong>：现代浏览器（基于 HTML5 规范）将 setTimeout 的延迟限制为至少 4ms，即使设置 delay=0： setTimeout(() =&gt; console.log(&#39;执行&#39;), 0); <em>// 实际延迟约 4ms</em></li><li><strong>原因</strong>：防止密集的任务阻塞事件循环，影响渲染和响应性。</li><li><strong>嵌套定时器</strong>：如果 setTimeout 嵌套超过 5 层，延迟会强制为 4ms： function nested() { setTimeout(() =&gt; { console.log(&#39;嵌套&#39;); nested(); }, 0);}nested(); <em>// 第 5 次后，延迟至少 4ms</em></li></ul><p><strong>漂移（Drift）问题</strong> 如果 setTimeout 回调的执行时间较长，会推迟下一次定时器的触发，导致实际间隔大于预期。这种现象称为“漂移”。示例： let start = Date.now();function tick() { <em>// 模拟耗时操作</em> for (let i = 0; i &lt; 1e7; i++) {} console.log(<code>间隔: ${Date.now() - start}ms</code>); start = Date.now(); setTimeout(tick, 100);}tick();<em>// 输出：<strong>// 间隔: 150ms （回调耗时约 50ms，实际间隔 150ms）</strong>// 间隔: 148ms （漂移持续）</em><strong>解决漂移</strong>：</p><ul><li>使用 setInterval 代替 setTimeout，但仍可能有漂移。</li><li>动态调整延迟时间（见代码示例）。</li></ul><p><strong>后台节流行为</strong></p><ul><li><strong>行为</strong>：当页面处于后台（不可视标签页、最小化窗口）或浏览器进入节能模式，浏览器会大幅降低定时器频率，通常限制为 1000ms 以上，甚至暂停。</li><li><strong>影响</strong>：实时数据更新（如报价或 K 线）会严重滞后。</li><li><strong>检测</strong>： document.addEventListener(&#39;visibilitychange&#39;, () =&gt; { console.log(&#39;页面状态:&#39;, document.visibilityState);});</li></ul><p><strong>4. 浏览器渲染机制</strong><strong>渲染流水线简介</strong> 浏览器渲染页面的过程包括：</p><ol><li><strong>解析</strong>：解析 HTML 和 CSS，构建 DOM 和 CSSOM 树。</li><li><strong>渲染树</strong>：结合 DOM 和 CSSOM，生成渲染树。</li><li><strong>布局（回流/Reflow）</strong>：计算元素的位置和大小。</li><li><strong>绘制（重绘/Repaint）</strong>：将像素绘制到屏幕。</li><li><strong>合成</strong>：将多个图层合成为最终图像。</li></ol><p><strong>重绘与回流</strong></p><ul><li><strong>回流</strong>：当 DOM 结构或布局属性（如 width、position）改变时，触发重新计算布局。成本高。 element.style.width = &#39;100px&#39;; <em>// 触发回流</em></li><li><strong>重绘</strong>：当样式（如 color、background）改变但不影响布局时，触发重绘。成本较低。 element.style.color = &#39;red&#39;; <em>// 触发重绘</em></li></ul><p><strong>渲染与事件循环的同步关系</strong></p><ul><li>渲染发生在事件循环的“渲染阶段”，通常每 16.7ms（60 FPS）触发一次。</li><li>HTML 规范保证渲染在定时器阶段之后，但不保证每次循环都渲染（取决于是否有 DOM 变化）。</li><li>如果 JavaScript 执行时间过长（超过 16.7ms），渲染会被推迟，导致“掉帧”或“卡顿”。</li></ul><p><strong>帧率与 16.7ms 的重要性</strong></p><ul><li><strong>60 FPS</strong>：浏览器目标是每秒 60 帧，即每帧 16.7ms。</li><li><strong>预算</strong>：每帧的 JavaScript 执行、渲染和合成总时间需控制在 16.7ms 内。</li><li><strong>掉帧</strong>：如果任务耗时过长，浏览器可能跳过渲染，导致视觉卡顿。</li></ul><p><strong>5. 与渲染同步的问题</strong><strong>更新抖动（Jank）的成因</strong></p><ul><li><strong>不同步</strong>：setTimeout 回调的执行时间与渲染阶段（每 16.7ms）不对齐，导致 UI 更新看起来不连贯。</li><li><strong>频繁更新</strong>：快速的 DOM 操作可能触发多次重绘，造成闪烁。</li><li>示例： setTimeout(() =&gt; { element.style.backgroundColor = &#39;red&#39;; <em>// 可能与渲染不同步</em>}, 10);</li></ul><p><strong>如何与浏览器重绘对齐</strong></p><ul><li>使用 requestAnimationFrame（rAF），其回调在渲染阶段（绘制前）执行： requestAnimationFrame(() =&gt; { element.style.backgroundColor = &#39;red&#39;; <em>// 与渲染同步</em>});</li><li><strong>优势</strong>：rAF 确保回调与浏览器重绘对齐，避免抖动。</li><li><strong>限制</strong>：rAF 不支持自定义延迟，需手动实现循环。</li></ul><p><strong>requestAnimationFrame 的作用</strong></p><ul><li><strong>用途</strong>：用于动画和需要与渲染同步的更新。</li><li><strong>特点</strong>： <ul><li>回调在下一帧的绘制前执行。</li><li>后台标签页会暂停 rAF 调用。</li><li>自动适配显示器的刷新率（如 120Hz 屏幕为 8.3ms/帧）。</li></ul></li><li>示例： function animate() { element.style.transform = <code>translateX(${Math.random() * 100}px)</code>; requestAnimationFrame(animate);}requestAnimationFrame(animate);</li></ul><p><strong>6. 累积延迟与实时性</strong><strong>累积延迟的来源</strong></p><ul><li><strong>回调耗时</strong>：setTimeout 回调的执行时间（如复杂计算）推迟下一次定时器。</li><li><strong>队列堵塞</strong>：宏任务队列中堆积的任务（如网络请求）延迟后续任务。</li><li><strong>漂移累积</strong>：多次 setTimeout 的延迟叠加，导致节奏变慢。</li></ul><p><strong>如何减少延迟</strong></p><ul><li><strong>优化回调</strong>：将耗时操作分解为小任务，或使用 Web Worker 卸载计算。</li><li><strong>动态延迟</strong>：调整 setTimeout 的延迟，补偿漂移： let last = Date.now();function tick() { const now = Date.now(); console.log(<code>实际间隔: ${now - last}ms</code>); last = now; setTimeout(tick, 100 - (now % 100)); <em>// 动态调整</em>}tick();</li><li><strong>微任务优先</strong>：将非阻塞逻辑放入微任务，减少宏任务队列压力： queueMicrotask(() =&gt; console.log(&#39;快速处理&#39;));</li></ul><p><strong>后台节流对实时性的影响</strong></p><ul><li><strong>影响</strong>：后台页面中，setTimeout 和 rAF 的调用频率降低，数据更新（如实时报价）可能暂停。</li><li><strong>解决</strong>： <ul><li>检测页面可见性，提示用户返回前台： document.addEventListener(&#39;visibilitychange&#39;, () =&gt; { if (document.visibilityState === &#39;hidden&#39;) { console.log(&#39;页面不可见，定时器可能被节流&#39;); }});</li><li>使用 WebSocket 或 Service Worker 维持数据更新（有限支持）。</li></ul></li></ul><p><strong>7. 解决方案与最佳实践</strong><strong>使用 useRafFn 实现与渲染同步</strong> useRafFn 是一个 Vue 组合式 API，结合 requestAnimationFrame 和节流逻辑，确保更新与渲染同步，同时控制频率。核心思想：</p><ul><li>使用 rAF 保证回调与重绘对齐。</li><li>添加节流机制，限制回调频率（如每 100ms）。</li></ul><p>实现（见代码示例）：</p><ul><li>创建 useRafFn 组合函数。</li><li>在组件中调用，传入回调和频率选项。</li></ul><p><strong>节流与防抖的结合</strong></p><ul><li><strong>节流（Throttle）</strong>：限制函数在固定时间间隔内只执行一次，适合实时更新： function throttle(fn, delay) { let last = 0; return function (...args) { const now = Date.now(); if (now - last &gt;= delay) { fn(...args); last = now; } };}</li><li><strong>防抖（Debounce）</strong>：延迟执行函数，直到停止触发一段时间，适合输入处理： function debounce(fn, delay) { let timer; return function (...args) { clearTimeout(timer); timer = setTimeout(() =&gt; fn(...args), delay); };}</li></ul><p><strong>处理后台节流问题</strong></p><ul><li><strong>检测可见性</strong>：使用 document.visibilityState 提示用户。</li><li><strong>替代方案</strong>：对于关键更新，使用 WebSocket 推送数据，结合本地存储缓存。</li><li><strong>降级策略</strong>：在后台时降低更新频率，恢复前台时同步数据。</li></ul><p><strong>8. 代码示例</strong><strong>简单的 setTimeout 示例</strong> 展示 setTimeout 的漂移问题： let start = Date.now();function tick() { <em>// 模拟耗时 50ms</em> const begin = Date.now(); while (Date.now() - begin &lt; 50) {} console.log(<code>间隔: ${Date.now() - start}ms</code>); start = Date.now(); setTimeout(tick, 100);}tick();<em>// 输出：间隔约 150ms（100ms 延迟 + 50ms 耗时）</em><strong>使用 requestAnimationFrame 同步渲染</strong> 实现平滑的 DOM 更新： javascript Copy const element = document.querySelector(&#39;#box&#39;);let x = 0;function move() { x += 1; element.style.transform = <code>translateX(${x % 100}px)</code>; requestAnimationFrame(move);}requestAnimationFrame(move); <strong>HTML</strong>： html Copy &lt;div id=&quot;box&quot; style=&quot;width: 50px; height: 50px; background: red;&quot;&gt;&lt;/div&gt; <strong>节流的 useRafFn 实现</strong> Vue 组合式 API，控制更新频率并同步渲染： javascript Copy _// src/composables/useRafFn.ts_import { ref, onMounted, onUnmounted } from &#39;vue&#39;; export function useRafFn(callback, { interval = 100 } = {}) { const last = ref(0); let rafId = null; function loop() { const now = Date.now(); if (now - last.value &gt;= interval) { callback(); last.value = now; } rafId = requestAnimationFrame(loop); } onMounted(() =&gt; { rafId = requestAnimationFrame(loop); }); onUnmounted(() =&gt; { if (rafId) cancelAnimationFrame(rafId); }); return { pause: () =&gt; cancelAnimationFrame(rafId), resume: () =&gt; { rafId = requestAnimationFrame(loop); }, };} <strong>使用</strong>： vue Copy &lt;template&gt; &lt;div :style=&quot;{ background: color }&quot;&gt;颜色变化&lt;/div&gt;&lt;/template&gt; &lt;script setup&gt;import { useRafFn } from &#39;@/composables/useRafFn&#39;;import { ref } from &#39;vue&#39;; const color = ref(&#39;red&#39;);useRafFn(() =&gt; { color.value = <code>hsl(${Math.random() * 360}, 50%, 50%)</code>;}, { interval: 1000 }); <em>// 每秒更新一次</em>&lt;/script&gt; <strong>处理后台节流的检测</strong> 检测页面不可见并提示： javascript Copy _// src/composables/useVisibility.ts_import { ref, onMounted, onUnmounted } from &#39;vue&#39;; export function useVisibility() { const isVisible = ref(document.visibilityState === &#39;visible&#39;); function handleChange() { isVisible.value = document.visibilityState === &#39;visible&#39;; } onMounted(() =&gt; { document.addEventListener(&#39;visibilitychange&#39;, handleChange); }); onUnmounted(() =&gt; { document.removeEventListener(&#39;visibilitychange&#39;, handleChange); }); return isVisible;} <strong>使用</strong>： vue Copy &lt;template&gt; &lt;div&gt;{{ isVisible ? &#39;页面可见，更新正常&#39; : &#39;页面不可见，更新可能延迟&#39; }}&lt;/div&gt;&lt;/template&gt; &lt;script setup&gt;import { useVisibility } from &#39;@/composables/useVisibility&#39;;const isVisible = useVisibility();&lt;/script&gt;</p><p><strong>9. 总结与注意事项</strong><strong>关键概念回顾</strong></p><ul><li><strong>事件循环</strong>：协调宏任务、微任务和渲染，确保单线程环境下任务按序执行。</li><li><strong>宏任务与 setTimeout</strong>：setTimeout 注册宏任务，受 4ms 限制、漂移和后台节流影响。</li><li><strong>渲染机制</strong>：每 16.7ms 尝试渲染一帧，JavaScript 执行过长会导致掉帧。</li><li><strong>同步问题</strong>：setTimeout 与渲染不同步，使用 requestAnimationFrame 可解决抖动。</li><li><strong>实时性</strong>：后台节流影响定时器，需检测页面状态或使用 WebSocket。</li></ul><p><strong>常见误区与建议</strong></p><ul><li><strong>误区</strong>：认为 setTimeout(fn, 0) 立即执行（实际延迟 4ms）。</li><li><strong>建议</strong>：动画更新使用 requestAnimationFrame，低频更新用节流的 setTimeout。</li><li><strong>误区</strong>：忽略后台节流，导致数据丢失。</li><li><strong>建议</strong>：结合 WebSocket 和本地缓存，确保关键数据更新。</li><li><strong>误区</strong>：频繁 DOM 操作导致性能问题。</li><li><strong>建议</strong>：批量更新 DOM，使用虚拟 DOM 或 requestAnimationFrame。</li></ul><p><strong>针对难点的简单代码说明</strong><strong>难点 1：漂移（Drift）</strong><strong>问题</strong>：setTimeout 回调耗时导致间隔变长。 <strong>简单代码</strong>： javascript Copy let last = Date.now();function tick() { <em>// 模拟耗时</em> const begin = Date.now(); while (Date.now() - begin &lt; 50) {} const now = Date.now(); console.log(<code>实际间隔: ${now - last}ms</code>); setTimeout(tick, Math.max(0, 100 - (now - last))); <em>// 补偿漂移</em> last = now;}tick();</p><p><strong>难点 2：更新抖动</strong><strong>问题</strong>：setTimeout 与渲染不同步，导致视觉不连贯。 <strong>简单代码</strong>： javascript Copy const element = document.querySelector(&#39;#box&#39;);let hue = 0;requestAnimationFrame(function update() { hue = (hue + 1) % 360; element.style.backgroundColor = <code>hsl(${hue}, 50%, 50%)</code>; requestAnimationFrame(update);}); <strong>HTML</strong>： html Copy &lt;div id=&quot;box&quot; style=&quot;width: 100px; height: 100px;&quot;&gt;&lt;/div&gt; <strong>难点 3：后台节流</strong><strong>问题</strong>：不可视页面中定时器暂停。 <strong>简单代码</strong>： javascript Copy setInterval(() =&gt; { if (document.visibilityState === &#39;visible&#39;) { console.log(&#39;更新数据&#39;); } else { console.log(&#39;页面不可见，暂停更新&#39;); }}, 1000);</p><p>通过本教程，你应该能够全面理解浏览器的事件循环、任务执行和渲染机制，以及如何处理 setTimeout 的局限性。如果需要更具体的实现（如在 Vue 项目中优化实时报价），请提供相关代码或场景，我可以进一步定制解决方案！</p></div>',1)])])}const d=o(s,[["render",n]]);export{p as __pageData,d as default};
